import os,re,subprocess,collections
pkgs=collections.defaultdict(list)  # dir -> names
for root,dirs,files in os.walk('internal'):
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            p=os.path.join(root,f)
            src=open(p).read()
            for m in re.finditer(r'^func (?:\([^)]*\)\s*)?([A-Za-z_]\w*)\(',src,re.M):
                pkgs[root].append((m.group(1),p,src[:m.start()].count('\n')+1))
# gather all go files non-test
allfiles=[]
for root,dirs,files in os.walk('.'):
    if any(x in root for x in ('/node_modules','/web','/.git','/proto/gen')): continue
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            allfiles.append(os.path.join(root,f))
contents={p:open(p).read() for p in allfiles}
imports={p:c for p,c in contents.items()}
res=[]
for d,names in pkgs.items():
    imp='github.com/usememos/memos/'+d
    scope=[p for p in allfiles if p.startswith('./'+d) or os.path.dirname(p)==d or imp+'"' in contents[p]]
    for name,decl,line in set(names):
        cnt=0
        for p in scope:
            c=contents[p]
            for m in re.finditer(r'(?<![A-Za-z0-9_])'+re.escape(name)+r'\(',c):
                # skip declaration lines
                ls=c.rfind('\n',0,m.start())+1
                if c[ls:].startswith('func '): continue
                cnt+=1
        res.append((cnt,name,decl,line))
res.sort(reverse=True)
for r in res[:20]: print(r)
